connection.py:
"""The connection to the world.

On a Raspberry Pi this is a socket to Minecraft Pi Edition on port 4711. In
PyIDE the world is in the same page, so there is no socket: each command is
handed to it directly (_pyide.command) and answered at once. The address and
port are accepted, so Minecraft.create("localhost", 4711) still works.
"""
from . import _pyide
from .util import flatten_parameters_to_string


class RequestError(Exception):
    """The world couldn't do what was asked (on a Pi, Minecraft answered Fail)."""


class Connection:
    def __init__(self, address="localhost", port=4711):
        self.address = address
        self.port = port
        self.lastSent = ""
        self._reply = ""

    def send(self, f, *data):
        line = "%s(%s)" % (f, flatten_parameters_to_string(data))
        self.lastSent = line
        self._reply = _pyide.command(line)
        if self._reply == "Fail":
            raise RequestError("%s failed" % line.strip())

    def receive(self):
        return self._reply

    def sendReceive(self, *data):
        self.send(*data)
        return self.receive()

    def drain(self):
        pass

    def close(self):
        pass

event.py:
"""What happened in the world since a program last asked: blocks hit, chat typed."""
from .vec3 import Vec3


class BlockEvent:
    """A block hit with the sword (the first slot of the world's hotbar)."""
    HIT = 0

    def __init__(self, type, x, y, z, face, entityId):
        self.type = type
        self.pos = Vec3(x, y, z)
        self.face = face
        self.entityId = entityId

    @staticmethod
    def Hit(x, y, z, face, entityId):
        return BlockEvent(BlockEvent.HIT, x, y, z, face, entityId)

    def __repr__(self):
        return "BlockEvent(%s, %d, %d, %d, %d, %d)" % (
            "BlockEvent.HIT" if self.type == BlockEvent.HIT else "???",
            self.pos.x, self.pos.y, self.pos.z, self.face, self.entityId)


class ChatEvent:
    """A line typed into the world's chat (press T in the world)."""
    POST = 0

    def __init__(self, type, entityId, message):
        self.type = type
        self.entityId = entityId
        self.message = message

    @staticmethod
    def Post(entityId, message):
        return ChatEvent(ChatEvent.POST, entityId, message)

    def __repr__(self):
        return "ChatEvent(%s, %d, %s)" % (
            "ChatEvent.POST" if self.type == ChatEvent.POST else "???", self.entityId, self.message)

minecraft.py:
"""The world, the player and the camera — what Minecraft.create() gives you.

    from mcpi.minecraft import Minecraft
    mc = Minecraft.create()
    mc.postToChat("Hello")
    pos = mc.player.getTilePos()
    mc.setBlock(pos.x + 1, pos.y, pos.z, 1)
"""
import math

from .block import Block
from .connection import Connection
from .event import BlockEvent, ChatEvent
from .util import flatten
from .vec3 import Vec3


def intFloor(*args):
    """Every number rounded down to a whole block, as the world wants them."""
    return [int(math.floor(value)) for value in flatten(args)]


class CmdPositioner:
    """Where an entity is, and moving it. The player is the one entity there is."""

    def __init__(self, connection, packagePrefix):
        self.conn = connection
        self.pkg = packagePrefix

    def getPos(self, id):
        s = self.conn.sendReceive(self.pkg + ".getPos", id)
        return Vec3(*[float(v) for v in s.split(",")])

    def setPos(self, id, *args):
        self.conn.send(self.pkg + ".setPos", id, args)

    def getTilePos(self, id):
        s = self.conn.sendReceive(self.pkg + ".getTile", id)
        return Vec3(*[int(v) for v in s.split(",")])

    def setTilePos(self, id, *args):
        self.conn.send(self.pkg + ".setTile", id, intFloor(*args))

    def getDirection(self, id):
        s = self.conn.sendReceive(self.pkg + ".getDirection", id)
        return Vec3(*[float(v) for v in s.split(",")])

    def getRotation(self, id):
        return float(self.conn.sendReceive(self.pkg + ".getRotation", id))

    def getPitch(self, id):
        return float(self.conn.sendReceive(self.pkg + ".getPitch", id))

    def setting(self, setting, status):
        self.conn.send(self.pkg + ".setting", setting, 1 if bool(status) else 0)


class CmdEntity(CmdPositioner):
    """Entities by id: mc.entity.getPos(id), with ids from mc.getPlayerEntityIds()."""

    def __init__(self, connection):
        CmdPositioner.__init__(self, connection, "entity")


class CmdPlayer(CmdPositioner):
    """The player: mc.player.getPos(), mc.player.setPos(x, y, z), …"""

    def __init__(self, connection):
        CmdPositioner.__init__(self, connection, "player")

    def getPos(self):
        return CmdPositioner.getPos(self, [])

    def setPos(self, *args):
        return CmdPositioner.setPos(self, [], args)

    def getTilePos(self):
        return CmdPositioner.getTilePos(self, [])

    def setTilePos(self, *args):
        return CmdPositioner.setTilePos(self, [], args)

    def getDirection(self):
        return CmdPositioner.getDirection(self, [])

    def getRotation(self):
        return CmdPositioner.getRotation(self, [])

    def getPitch(self):
        return CmdPositioner.getPitch(self, [])


class CmdCamera:
    """Where the view is from: the player's eyes, behind them, or a fixed point."""

    def __init__(self, connection):
        self.conn = connection

    def setNormal(self, *args):
        self.conn.send("camera.mode.setNormal", args)

    def setFixed(self):
        self.conn.send("camera.mode.setFixed")

    def setFollow(self, *args):
        self.conn.send("camera.mode.setFollow", args)

    def setPos(self, *args):
        self.conn.send("camera.setPos", args)


class CmdEvents:
    """What happened since you last asked: blocks hit with the sword, chat typed."""

    def __init__(self, connection):
        self.conn = connection

    def clearAll(self):
        self.conn.send("events.clear")

    def pollBlockHits(self):
        s = self.conn.sendReceive("events.block.hits")
        return [BlockEvent.Hit(*[int(v) for v in e.split(",")]) for e in s.split("|") if e]

    def pollChatPosts(self):
        s = self.conn.sendReceive("events.chat.posts")
        posts = []
        for e in s.split("|"):
            if e:
                comma = e.find(",")
                posts.append(ChatEvent.Post(int(e[:comma]), e[comma + 1:]))
        return posts


class Minecraft:
    """The world: blocks, chat, checkpoints, and mc.player, mc.camera, mc.events."""

    def __init__(self, connection):
        self.conn = connection
        self.camera = CmdCamera(connection)
        self.entity = CmdEntity(connection)
        self.player = CmdPlayer(connection)
        self.events = CmdEvents(connection)

    def getBlock(self, *args):
        return int(self.conn.sendReceive("world.getBlock", intFloor(args)))

    def getBlockWithData(self, *args):
        s = self.conn.sendReceive("world.getBlockWithData", intFloor(args))
        return Block(*[int(v) for v in s.split(",")])

    def setBlock(self, *args):
        self.conn.send("world.setBlock", intFloor(args))

    def setBlocks(self, *args):
        self.conn.send("world.setBlocks", intFloor(args))

    def getHeight(self, *args):
        return int(self.conn.sendReceive("world.getHeight", intFloor(args)))

    def getPlayerEntityIds(self):
        s = self.conn.sendReceive("world.getPlayerIds")
        return [int(v) for v in s.split("|") if v]

    def saveCheckpoint(self):
        self.conn.send("world.checkpoint.save")

    def restoreCheckpoint(self):
        self.conn.send("world.checkpoint.restore")

    def postToChat(self, msg):
        # One line of chat: a newline would end the command on a Pi too.
        self.conn.send("chat.post", str(msg).replace("\n", " "))

    def setting(self, setting, status):
        self.conn.send("world.setting", setting, 1 if bool(status) else 0)

    @staticmethod
    def create(address="localhost", port=4711):
        return Minecraft(Connection(address, port))

util.py:
"""Turning arguments into the comma-separated text the protocol carries."""


def flatten(items):
    """Every value in nested lists, tuples, Vec3s and Blocks, in order —
    so setBlock(pos, block.WOOL.withData(14)) sends x,y,z,35,14."""
    for item in items:
        if isinstance(item, (str, bytes)):
            yield item
            continue
        try:
            inner = iter(item)
        except TypeError:
            yield item
            continue
        for value in flatten(inner):
            yield value


def flatten_parameters_to_string(items):
    return ",".join(str(value) for value in flatten(items))

vec3.py:
"""A point or a direction in the world: x across, y up, z the other way across."""
import math


class Vec3:
    def __init__(self, x=0, y=0, z=0):
        self.x = x
        self.y = y
        self.z = z

    def clone(self):
        return Vec3(self.x, self.y, self.z)

    def __iter__(self):
        return iter((self.x, self.y, self.z))

    def __add__(self, other):
        return Vec3(self.x + other.x, self.y + other.y, self.z + other.z)

    def __sub__(self, other):
        return Vec3(self.x - other.x, self.y - other.y, self.z - other.z)

    def __mul__(self, k):
        return Vec3(self.x * k, self.y * k, self.z * k)

    __rmul__ = __mul__

    def __neg__(self):
        return Vec3(-self.x, -self.y, -self.z)

    def __iadd__(self, other):
        self.x += other.x
        self.y += other.y
        self.z += other.z
        return self

    def __isub__(self, other):
        self.x -= other.x
        self.y -= other.y
        self.z -= other.z
        return self

    def __imul__(self, k):
        self.x *= k
        self.y *= k
        self.z *= k
        return self

    def length(self):
        return math.sqrt(self.lengthSqr())

    def lengthSqr(self):
        return self.x * self.x + self.y * self.y + self.z * self.z

    def _key(self):
        return (self.x, self.y, self.z)

    def __eq__(self, other):
        return isinstance(other, Vec3) and self._key() == other._key()

    def __ne__(self, other):
        return not self == other

    def __lt__(self, other):
        return self._key() < other._key()

    def __le__(self, other):
        return self._key() <= other._key()

    def __gt__(self, other):
        return self._key() > other._key()

    def __ge__(self, other):
        return self._key() >= other._key()

    def __hash__(self):
        return hash(self._key())

    def rotateLeft(self):
        self.x, self.z = self.z, -self.x
        return self

    def rotateRight(self):
        self.x, self.z = -self.z, self.x
        return self

    def __repr__(self):
        return "Vec3(%s,%s,%s)" % (self.x, self.y, self.z)
